    #[doc = ""]
    #[doc = " # Examples"]
    #[doc = ""]
    #[doc = " Before:"]
    #[doc = ""]
    #[doc = " ```text"]
    #[doc = " <rect fill=\"red\"/>"]
    #[doc = " ```"]
    #[doc = ""]
    #[doc = " After:"]
    #[doc = ""]
    #[doc = " ```text"]
    #[doc = " <rect fill='red'/>"]
    #[doc = " ```"]
