    #[doc = ""]
    #[doc = " # Examples"]
    #[doc = ""]
    #[doc = " `Indent::None`"]
    #[doc = " Before:"]
    #[doc = ""]
    #[doc = " ```text"]
    #[doc = " <svg>"]
